/// Trader-facing set: unlocks partner SwapPair rows.
/// Wire calls send [NetworkRow.swapPairId] as u8.
enum SwapPairSdk {
  sol(0, 'SOL', 'XFG/SOL'),
  eth(1, 'ETH', 'XFG/ETH'),
  xmr(2, 'XMR', 'XFG/XMR'),
  bch(3, 'BCH', 'XFG/BCH'),
  arb(4, 'ARB', 'XFG/ARB'),
  base(5, 'BASE', 'XFG/BASE'),
  kmd(6, 'KMD', 'XFG/KMD'),
  bnb(7, 'BNB', 'XFG/BNB'),
  dcr(8, 'DCR', 'XFG/DCR'),
  btc(9, 'BTC', 'XFG/BTC'),
  ltc(10, 'LTC', 'XFG/LTC'),
  poly(11, 'POLY', 'XFG/POLY'),
  gleec(12, 'GLEEC', 'XFG/GLEEC'),
  robinhood(13, 'RHC', 'XFG/RHC'),
  avax(14, 'AVAX', 'XFG/AVAX'),
  cro(15, 'CRO', 'XFG/CRO'),
  bob(16, 'BOB', 'XFG/BOB'),
  unichain(18, 'UNI', 'XFG/UNI'),
  plasma(19, 'XPL', 'XFG/XPL'),
  doge(20, 'DOGE', 'XFG/DOGE'),
  dash(21, 'DASH', 'XFG/DASH'),
  zec(22, 'ZEC', 'XFG/ZEC'),
  pulsex(23, 'PLS', 'XFG/PLS'),
  monad(25, 'MON', 'XFG/MON'),
  optimism(26, 'OP', 'XFG/OP');

  final int id;
  final String ticker;
  final String displayName;
  const SwapPairSdk(this.id, this.ticker, this.displayName);

  static SwapPairSdk? tryFromId(int id) {
    for (final pair in values) {
      if (pair.id == id) return pair;
    }
    return null;
  }

  /// Throws. An unknown id is not ETH.
  static SwapPairSdk fromId(int id) {
    final pair = tryFromId(id);
    if (pair == null) {
      throw ArgumentError('unknown swap pair id $id');
    }
    return pair;
  }

  static NetworkRow? rowFor(SwapPairSdk pair) {
    for (final row in kReadyNetworks) {
      if (row.swapPairId == pair.id) return row;
    }
    return null;
  }
}

NetworkRow? networkBySwapPairId(int id) {
  for (final row in kNetworkCatalog) {
    if (row.swapPairId == id) return row;
  }
  return null;
}

